class Solution:
    def minOperations(self, target: List[int], arr: List[int]) -> int:
        n, m = len(target), len(arr)
        dp = [[0] * (m + 1) for _ in range(n + 1)]
        for i in range(1, n + 1):
            for j in range(1, m + 1):
                if target[i - 1] == arr[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] + 1
                else:
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
        return n - dp[n][m]

