from bisect import bisect_left


class Solution:
    def minOperations(self, target: List[int], arr: List[int]) -> int:
        rank = {v: i for i, v in enumerate(target)}
        tails = []
        for v in arr:
            if v not in rank:
                continue
            x = rank[v]
            pos = bisect_left(tails, x)
            if pos == len(tails):
                tails.append(x)
            else:
                tails[pos] = x
        return len(target) - len(tails)

