class Solution {
public:
    int minOperations(vector<int>& target, vector<int>& arr) {
        unordered_map<int, int> rank;
        for (int i = 0; i < (int)target.size(); ++i) rank[target[i]] = i;
        vector<int> tails;
        for (int v : arr) {
            auto it = rank.find(v);
            if (it == rank.end()) continue;
            int x = it->second;
            auto pos = lower_bound(tails.begin(), tails.end(), x);
            if (pos == tails.end()) tails.push_back(x);
            else *pos = x;
        }
        return (int)(target.size() - tails.size());
    }
};

