var minOperations = function(target, arr) {
    const rank = new Map(target.map((v, i) => [v, i]));
    const tails = [];
    const lowerBound = (x) => {
        let lo = 0, hi = tails.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (tails[mid] < x) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    };
    for (const v of arr) {
        if (!rank.has(v)) continue;
        const x = rank.get(v), pos = lowerBound(x);
        if (pos === tails.length) tails.push(x);
        else tails[pos] = x;
    }
    return target.length - tails.length;
};
